@push('scripts')
<script src="{{ asset('assets/js/vendor/jspdf.umd.min.js') }}"></script>
<script>
function getValidPasscodes() {
  const lockScreen = document.getElementById('idCardLockScreen');
  const envPwd = lockScreen ? lockScreen.getAttribute('data-password') : '';
  const passcodes = ['croydon2026', 'cce2026', 'croydon'];
  if (envPwd && !passcodes.includes(envPwd)) {
    passcodes.unshift(envPwd);
  }
  return passcodes.map(p => String(p).toLowerCase());
}

function unlockCardMaker(e) {
  if (e) e.preventDefault();
  const inputEl = document.getElementById('passcodeInput');
  const val = (inputEl ? inputEl.value : '').trim().toLowerCase();
  const validPasscodes = getValidPasscodes();
  if (validPasscodes.includes(val)) {
    sessionStorage.setItem('id_card_unlocked', 'true');
    showCardMaker();
  } else {
    const pwdErr = document.getElementById('pwdError');
    if (pwdErr) pwdErr.style.display = 'block';
  }
}

function lockCardMaker() {
  sessionStorage.removeItem('id_card_unlocked');
  const lockScreen = document.getElementById('idCardLockScreen');
  const cardContent = document.getElementById('idCardContent');
  if (lockScreen) lockScreen.style.display = 'block';
  if (cardContent) cardContent.style.display = 'none';
  const inputEl = document.getElementById('passcodeInput');
  if (inputEl) {
    inputEl.value = '';
    inputEl.focus();
  }
  const pwdErr = document.getElementById('pwdError');
  if (pwdErr) pwdErr.style.display = 'none';
}

function showCardMaker() {
  const lockScreen = document.getElementById('idCardLockScreen');
  const cardContent = document.getElementById('idCardContent');
  if (lockScreen) lockScreen.style.display = 'none';
  if (cardContent) cardContent.style.display = 'block';
  if (typeof draw === 'function') draw();
}

document.addEventListener('DOMContentLoaded', function() {
    const NAVY = '#185276', GOLD = '#be9446', W = 2024, H = 1276;
    const FONT = 'Calibri,Carlito,"Segoe UI",Arial,sans-serif';
    const $ = id => document.getElementById(id);
    const logo = new Image(), photo = new Image();
    let hasPhoto = false;

    window.draw = function() {
      drawFront();
      drawBack();
    };

    logo.onload = function() { if (typeof draw === 'function') draw(); };
    photo.onload = function() { hasPhoto = true; if (typeof draw === 'function') draw(); };

    logo.src = 'data:image/png;base64,';
    photo.src = 'data:image/jpeg;base64,';

    const photoInput = $('photo');
    if (photoInput) {
      photoInput.addEventListener('change', e => {
        const f = e.target.files[0]; if (!f) return;
        const r = new FileReader();
        r.onload = () => { photo.src = r.result; $('zoom').value = 100; $('px').value = 0; $('py').value = 0; };
        r.readAsDataURL(f);
      });
    }

    document.querySelectorAll('input[type=text],input[type=range]').forEach(i => i.addEventListener('input', draw));

    function fit(ctx, text, weight, size, maxW, min = 40) {
      while (size > min) { ctx.font = weight + ' ' + size + 'px ' + FONT; if (ctx.measureText(text).width <= maxW) break; size -= 2; }
      ctx.font = weight + ' ' + size + 'px ' + FONT;
    }
    function ctext(ctx, t, cx, cy, weight, size, color, maxW) {
      fit(ctx, t, weight, size, maxW); ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(t, cx, cy);
    }
    function drawLogo(ctx, h, cx, y) { const w = logo.width * h / logo.height; ctx.drawImage(logo, cx - w / 2, y, w, h); }

    function drawFront() {
      const c = $('front'); if (!c) return;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = NAVY; ctx.fillRect(0, 700, W, H - 700);
      ctx.fillStyle = GOLD; ctx.fillRect(0, H - 26, W, 26);
      if (logo.complete && logo.naturalWidth) drawLogo(ctx, 560, 640, 70);

      // photo frame
      const pw = 584, ph = 848, fx = 1340, fy = 70, pad = 10, bd = 10, out = pw + 2 * (pad + bd), outH = ph + 2 * (pad + bd);
      ctx.fillStyle = '#bfbfbf'; ctx.fillRect(fx, fy, out, outH);
      ctx.fillStyle = '#fff'; ctx.fillRect(fx + bd, fy + bd, out - 2 * bd, outH - 2 * bd);
      const ix = fx + bd + pad, iy = fy + bd + pad;
      ctx.save(); ctx.beginPath(); ctx.rect(ix, iy, pw, ph); ctx.clip();
      if (hasPhoto && photo.naturalWidth) {
        const z = $('zoom').value / 100, s = Math.max(pw / photo.width, ph / photo.height) * z;
        const dw = photo.width * s, dh = photo.height * s;
        const mx = (dw - pw) / 2, my = (dh - ph) / 2;
        const x = ix - mx - ($('px').value / 100) * mx, y = iy - my - ($('py').value / 100) * my;
        ctx.drawImage(photo, x, y, dw, dh);
      } else {
        ctx.fillStyle = '#e9edf1'; ctx.fillRect(ix, iy, pw, ph);
        ctx.fillStyle = '#b8c2cc'; ctx.beginPath(); ctx.arc(ix + pw / 2, iy + 300, 120, 0, 7); ctx.fill();
        ctx.beginPath(); ctx.ellipse(ix + pw / 2, iy + ph, 260, 330, 0, 0, 7); ctx.fill();
      }
      ctx.restore();

      ctext(ctx, $('name').value.trim(), 660, 940, 'bold', 138, '#fff', 1180);
      ctx.fillStyle = GOLD; ctx.fillRect(360, 1042, 600, 6);
      ctext(ctx, $('title').value.trim(), 660, 1150, 'normal', 96, '#fff', 1180);
    }

    function drawBack() {
      const c = $('back'); if (!c) return;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = NAVY; ctx.fillRect(0, 430, W, H - 430);
      ctx.fillStyle = GOLD; ctx.fillRect(0, H - 26, W, 26);
      if (logo.complete && logo.naturalWidth) drawLogo(ctx, 360, W / 2, 40);
      const cx = W / 2, M = 1850;
      ctext(ctx, $('head').value, cx, 545, 'bold', 100, '#ebc882', M);
      ctext(ctx, $('org').value, cx, 685, 'bold', 84, '#fff', M);
      ctext(ctx, $('a1').value, cx, 810, 'normal', 70, '#fff', M);
      ctext(ctx, $('a2').value, cx, 895, 'normal', 70, '#fff', M);
      ctx.fillStyle = GOLD; ctx.fillRect(cx - 300, 972, 600, 5);
      ctext(ctx, $('tel').value, cx, 1045, 'normal', 70, '#fff', M);
      ctext(ctx, $('mail').value, cx, 1135, 'normal', 70, '#fff', M);
    }

    function fname(side) { return ($('name').value.trim().replace(/[^\w]+/g, '_') || 'id_card') + '_' + side + '.png'; }
    function save(canvas, name, e) {
      if (e) { e.preventDefault(); e.stopPropagation(); }
      const a = document.createElement('a');
      a.href = canvas.toDataURL('image/png');
      a.download = name;
      a.click();
    }
    if ($('dlF')) $('dlF').onclick = (e) => save($('front'), fname('front'), e);
    if ($('dlB')) $('dlB').onclick = (e) => save($('back'), fname('back'), e);
    if ($('dlBoth')) $('dlBoth').onclick = (e) => {
      if (e) { e.preventDefault(); e.stopPropagation(); }
      save($('front'), fname('front'));
      setTimeout(() => save($('back'), fname('back')), 400);
    };

    function downloadPdf(e) {
      if (e) {
        e.preventDefault();
        e.stopPropagation();
      }
      const jsPDF = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
      if (!jsPDF) {
        alert('PDF generator library is still loading. Please try again in a moment.');
        return;
      }
      try {
        const doc = new jsPDF({
          orientation: 'landscape',
          unit: 'mm',
          format: [85.6, 54]
        });
        const frontCanvas = $('front');
        const backCanvas = $('back');
        if (!frontCanvas || !backCanvas) return;

        const frontImg = frontCanvas.toDataURL('image/png');
        doc.addImage(frontImg, 'PNG', 0, 0, 85.6, 54);

        doc.addPage([85.6, 54], 'landscape');
        const backImg = backCanvas.toDataURL('image/png');
        doc.addImage(backImg, 'PNG', 0, 0, 85.6, 54);

        const filename = ($('name').value.trim().replace(/[^\w]+/g, '_') || 'id_card') + '_id_card.pdf';
        doc.save(filename);
      } catch (err) {
        console.error('PDF generation error:', err);
        alert('Error generating PDF: ' + err.message);
      }
    }

    const dlPdfBtn = $('dlPdf') || $('prt');
    if (dlPdfBtn) dlPdfBtn.onclick = downloadPdf;

    if (sessionStorage.getItem('id_card_unlocked') === 'true') {
      showCardMaker();
    }
});
</script>
@endpush
